"use strict";(globalThis.webpackChunkmy_maker_blog=globalThis.webpackChunkmy_maker_blog||[]).push([[225],{3464:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/flash-process","metadata":{"permalink":"/my-maker-blog/blog/flash-process","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/flash-process/index.md","source":"@site/blog/flash-process/index.md","title":"\u5c0f\u667a AI \u70e7\u5f55\u6307\u5357\uff08\u867e\u54e5\u7248\uff09","description":"\u4ece\u96f6\u5f00\u59cb\u70e7\u5f55\u867e\u54e5\u5c0f\u667a AI \u5230 ESP32 \u7684\u5b8c\u6574\u6d41\u7a0b\u8bf4\u660e","date":"2026-01-10T03:37:06.630Z","tags":[],"readingTime":2.02,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"\u5c0f\u667a AI \u70e7\u5f55\u6307\u5357\uff08\u867e\u54e5\u7248\uff09","sidebar_position":1,"description":"\u4ece\u96f6\u5f00\u59cb\u70e7\u5f55\u867e\u54e5\u5c0f\u667a AI \u5230 ESP32 \u7684\u5b8c\u6574\u6d41\u7a0b\u8bf4\u660e"},"unlisted":false,"nextItem":{"title":"Welcome to My Blog","permalink":"/my-maker-blog/blog/welcome"}},"content":"\u672c\u6587\u5c06\u8be6\u7ec6\u4ecb\u7ecd **\u867e\u54e5\u5c0f\u667a AI** \u7684\u5b8c\u6574\u70e7\u5f55\u6d41\u7a0b\uff0c\u9002\u5408**\u7b2c\u4e00\u6b21\u63a5\u89e6 ESP32 / \u5c0f\u667a AI \u7684\u65b0\u624b**\uff0c\u4e5f\u53ef\u4f5c\u4e3a\u9879\u76ee\u590d\u73b0\u4e0e\u6559\u5b66\u6587\u6863\u4f7f\u7528\u3002\\r\\n\\r\\n\\r\\n\\r\\n## \u4e00\u3001\u4f60\u5c06\u83b7\u5f97\u4ec0\u4e48\uff1f\\r\\n\\r\\n\u5b8c\u6210\u672c\u6559\u7a0b\u540e\uff0c\u4f60\u5c06\u80fd\u591f\uff1a\\r\\n\\r\\n- \u2705 \u5c06 **\u5c0f\u667a AI \u56fa\u4ef6\u6210\u529f\u70e7\u5f55\u5230 ESP32S3\\r\\n- \u2705 \u5728\u7f51\u9875\u7aef\u8c03\u8bd5\u548c\u4fee\u6539 AI Prompt\\r\\n- \u2705 \u8ba9\u5c0f\u667a AI \u6b63\u5e38\u8054\u7f51\u3001\u5bf9\u8bdd\u3001\u54cd\u5e94\\r\\n- \u2705 \u4e3a\u540e\u7eed **\u591a\u667a\u80fd\u4f53 / \u54f2\u5b66\u89d2\u8272\u5b9a\u5236** \u6253\u597d\u57fa\u7840\\r\\n\\r\\n\\r\\n## \u4e8c\u3001\u786c\u4ef6\u4e0e\u8f6f\u4ef6\u51c6\u5907\\r\\n\\r\\n### 1\ufe0f\u20e3 \u786c\u4ef6\u6e05\u5355\\r\\n\\r\\n- ESP32 \u5f00\u53d1\u677f\uff08\u63a8\u8350 ESP32-WROOM \u7cfb\u5217\uff09\\r\\n- USB \u6570\u636e\u7ebf\uff08**\u6ce8\u610f\u4e0d\u662f\u53ea\u5145\u7535\u7ebf**\uff09\\r\\n- \u7a33\u5b9a\u7684 Wi-Fi \u7f51\u7edc\\r\\n- \u4e00\u53f0\u7535\u8111\uff08Windows / macOS \u5747\u53ef\uff09\\r\\n\\r\\n\\r\\n### 2\ufe0f\u20e3 \u8f6f\u4ef6\u4e0e\u5de5\u5177\\r\\n\\r\\n\u8bf7\u63d0\u524d\u51c6\u5907\u4ee5\u4e0b\u73af\u5883\uff1a\\r\\n\\r\\n- **Google Chrome / Edge \u6d4f\u89c8\u5668**\\r\\n- **\u867e\u54e5\u5c0f\u667a AI \u5b98\u65b9\u70e7\u5f55\u7f51\u9875**\\r\\n- ESP32 USB \u9a71\u52a8\uff08\u5982 CP210x / CH340\uff09\\r\\n\\r\\n> \ud83d\udca1 \u5982\u679c\u7535\u8111\u65e0\u6cd5\u8bc6\u522b ESP32 \u4e32\u53e3\uff0c\u901a\u5e38\u662f\u9a71\u52a8\u672a\u5b89\u88c5\u3002\\r\\n\\r\\n\\r\\n\\r\\n## \u4e09\u3001\u8fdb\u5165\u5c0f\u667a AI \u70e7\u5f55\u9875\u9762\\r\\n\\r\\n\u6253\u5f00\u867e\u54e5\u5c0f\u667a AI \u5b98\u65b9\u70e7\u5f55\u7f51\u9875\uff1a\\r\\n\\r\\n\ud83d\udc49 **https://xiaozhi.me/**\uff08\u793a\u4f8b\u5730\u5740\uff0c\u8bf7\u4ee5\u5b9e\u9645\u4e3a\u51c6\uff09\\r\\n\\r\\n\u5728\u9996\u9875\u4f60\u53ef\u4ee5\u770b\u5230\uff1a\\r\\n\\r\\n- \u56fa\u4ef6\u9009\u62e9\\r\\n- \u4e32\u53e3\u8fde\u63a5\\r\\n- \u7f51\u7edc\u914d\u7f6e\\r\\n- Prompt / Agent \u8bbe\u7f6e\\r\\n\\r\\n\\r\\n## \u56db\u3001ESP32 \u8fde\u63a5\u4e0e\u70e7\u5f55\u6b65\u9aa4\\r\\n\\r\\n### Step 1\uff1a\u8fde\u63a5\u5f00\u53d1\u677f\\r\\n\\r\\n1. \u4f7f\u7528 USB \u7ebf\u5c06 ESP32 \u8fde\u63a5\u7535\u8111  \\r\\n2. \u70b9\u51fb\u7f51\u9875\u4e2d\u7684 **\u300c\u8fde\u63a5\u8bbe\u5907 / Connect\u300d**\\r\\n3. \u5728\u5f39\u7a97\u4e2d\u9009\u62e9\u5bf9\u5e94\u7684 **COM / USB \u7aef\u53e3**\\r\\n\\r\\n\\r\\n\\r\\n### Step 2\uff1a\u9009\u62e9\u56fa\u4ef6\\r\\n\\r\\n\u5728\u56fa\u4ef6\u9009\u9879\u4e2d\uff1a\\r\\n\\r\\n- \u9009\u62e9 **\u6700\u65b0\u7a33\u5b9a\u7248\u5c0f\u667a AI \u56fa\u4ef6**\\r\\n- \u5982\u679c\u4f60\u662f\u7b2c\u4e00\u6b21\u70e7\u5f55\uff0c\u5efa\u8bae\uff1a\\r\\n  - \u274c \u4e0d\u8981\u9009 beta\\r\\n  - \u274c \u4e0d\u8981\u9009\u81ea\u5b9a\u4e49\u5206\u652f\\r\\n\\r\\n\\r\\n\\r\\n### Step 3\uff1a\u5f00\u59cb\u70e7\u5f55\\r\\n\\r\\n1. \u70b9\u51fb **\u300c\u70e7\u5f55 / Flash\u300d**\\r\\n2. \u7b49\u5f85\u8fdb\u5ea6\u6761\u5b8c\u6210\uff08\u7ea6 1\u20133 \u5206\u949f\uff09\\r\\n3. \u770b\u5230 **Flash Success / \u70e7\u5f55\u6210\u529f** \u63d0\u793a\\r\\n\\r\\n\u26a0\ufe0f **\u70e7\u5f55\u8fc7\u7a0b\u4e2d\u8bf7\u52ff\u62d4\u7ebf\u6216\u5237\u65b0\u9875\u9762**\\r\\n\\r\\n---\\r\\n\\r\\n## \u4e94\u3001\u7f51\u7edc\u914d\u7f6e\uff08\u975e\u5e38\u5173\u952e\uff09\\r\\n\\r\\n\u70e7\u5f55\u5b8c\u6210\u540e\uff0c\u5c0f\u667a AI \u9700\u8981\u8054\u7f51\u624d\u80fd\u5de5\u4f5c\u3002\\r\\n\\r\\n### \u914d\u7f6e\u6b65\u9aa4\uff1a\\r\\n\\r\\n- \u8f93\u5165 Wi-Fi \u540d\u79f0\uff08SSID\uff09\\r\\n- \u8f93\u5165 Wi-Fi \u5bc6\u7801\\r\\n- \u70b9\u51fb **\u4fdd\u5b58 / Save**\\r\\n- \u7b49\u5f85\u8bbe\u5907\u81ea\u52a8\u91cd\u542f\\r\\n\\r\\n\ud83d\udce1 \u5f53\u4f60\u770b\u5230\u4e32\u53e3\u65e5\u5fd7\u4e2d\u51fa\u73b0\u8054\u7f51\u6210\u529f\u4fe1\u606f\uff0c\u8bf4\u660e\u914d\u7f6e\u5b8c\u6210\u3002\\r\\n\\r\\n\\r\\n## \u516d\u3001\u7f51\u9875\u7aef\u8c03\u8bd5\u4e0e Prompt \u8bbe\u7f6e\\r\\n\\r\\n\u70e7\u5f55\u6210\u529f\u540e\uff0c\u4f60\u53ef\u4ee5\u5728\u7f51\u9875\u7aef\u76f4\u63a5\u63a7\u5236\u5c0f\u667a AI \u7684\u884c\u4e3a\u3002\\r\\n\\r\\n### \u4f60\u53ef\u4ee5\u505a\u4ec0\u4e48\uff1f\\r\\n\\r\\n- \u270f\ufe0f \u4fee\u6539 AI \u7684 **\u89d2\u8272 Prompt**\\r\\n- \ud83c\udf10 \u8bbe\u7f6e\u4e2d\u82f1\u6587\u8f93\u51fa\\r\\n- \ud83e\udde0 \u8bbe\u5b9a\u6027\u683c\u3001\u8bed\u6c14\u3001\u77e5\u8bc6\u8fb9\u754c\\r\\n- \ud83d\udd01 \u5b9e\u65f6\u8c03\u8bd5 AI \u54cd\u5e94\u6548\u679c\\r\\n\\r\\n\u4f8b\u5982\uff1a\\r\\n\\r\\n```text\\r\\n\u4f60\u662f\u4e00\u4e2a\u54f2\u5b66 AI\uff0c\u64c5\u957f\u7528\u901a\u4fd7\u8bed\u8a00\u89e3\u91ca\u590d\u6742\u601d\u60f3\u3002"},{"id":"welcome","metadata":{"permalink":"/my-maker-blog/blog/welcome","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/welcome.md","source":"@site/blog/welcome.md","title":"Welcome to My Blog","description":"Welcome to my maker journey blog! This is where I\'ll share my projects, learnings, and experiences.","date":"2025-12-31T03:35:44.000Z","tags":[{"inline":true,"label":"welcome","permalink":"/my-maker-blog/blog/tags/welcome"}],"readingTime":0.1,"hasTruncateMarker":false,"authors":[{"name":"Sunny (Xinrong Sun)","title":"Maker & Student at Duke Kunshan University","url":"https://github.com/Sunny156-hungry","page":{"permalink":"/my-maker-blog/blog/authors/sunny"},"socials":{"github":"https://github.com/Sunny156-hungry"},"imageURL":"https://github.com/Sunny156-hungry.png","key":"sunny"}],"frontMatter":{"slug":"welcome","title":"Welcome to My Blog","authors":["sunny"],"tags":["welcome"]},"unlisted":false,"prevItem":{"title":"\u5c0f\u667a AI \u70e7\u5f55\u6307\u5357\uff08\u867e\u54e5\u7248\uff09","permalink":"/my-maker-blog/blog/flash-process"},"nextItem":{"title":"Twin Agents","permalink":"/my-maker-blog/blog/blog/twin-agents"}},"content":"Welcome to my maker journey blog! This is where I\'ll share my projects, learnings, and experiences.\\r\\n\\r\\nMore posts coming soon..."},{"id":"/blog/twin-agents","metadata":{"permalink":"/my-maker-blog/blog/blog/twin-agents","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/twin-agents/index.mdx","source":"@site/blog/twin-agents/index.mdx","title":"Twin Agents","description":"An interactive AI project featuring Schopenhauer and Hegel","date":"2025-12-31T00:00:00.000Z","tags":[{"inline":true,"label":"ai","permalink":"/my-maker-blog/blog/tags/ai"},{"inline":true,"label":"philosophy","permalink":"/my-maker-blog/blog/tags/philosophy"},{"inline":true,"label":"multi-agent","permalink":"/my-maker-blog/blog/tags/multi-agent"}],"readingTime":1.53,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"Twin Agents","date":"2025-12-31T00:00:00.000Z","slug":"/blog/twin-agents","tags":["ai","philosophy","multi-agent"],"image":"/img/cover.jpg","description":"An interactive AI project featuring Schopenhauer and Hegel"},"unlisted":false,"prevItem":{"title":"Welcome to My Blog","permalink":"/my-maker-blog/blog/welcome"}},"content":"## Project Introduction\\r\\n\\r\\n**Twin Agents** is an interactive AI project featuring two philosophical agents modeled after **Arthur Schopenhauer** and **Georg Wilhelm Friedrich Hegel**.\\r\\n\\r\\nUsers can engage in conversations with each agent individually or observe dialogues between the two. Through these interactions, the project aims to spark curiosity about philosophy and help users gain a deeper, more accessible understanding of philosophical ideas.\\r\\n\\r\\n\\r\\n## \ud83c\udfa5 Project Demo\\r\\n\\r\\n\\r\\n<iframe\\r\\n  src=\\"https://player.bilibili.com/player.html?bvid=BV15JrNBgEDD&high_quality=1\\"\\r\\n  style={{ width: \\"100%\\", height: \\"420px\\", borderRadius: \\"12px\\" }}\\r\\n  frameBorder=\\"0\\"\\r\\n  allow=\\"autoplay; fullscreen; picture-in-picture\\"\\r\\n  allowFullScreen\\r\\n/>\\r\\n\\r\\n## Key Features\\r\\n\\r\\n- Two AI agents collaborate to overcome common issues in one-on-one AI conversations, such as boredom, stalled discussions, and informational echo chambers.\\r\\n- The project explores the concept of **1 + 1 > 2** in multi-agent intelligence.\\r\\n- The agents tease each other, debate opposing viewpoints, and generate intellectual friction, encouraging users to think critically and stay engaged.\\r\\n\\r\\n\\r\\n## Target Users\\r\\n\\r\\n- Philosophy enthusiasts  \\r\\n- General audiences with little or no formal background in philosophy\\r\\n\\r\\n\\r\\n## Why This Project\\r\\n\\r\\nMany people today perceive philosophy as distant from everyday life and therefore unimportant.  \\r\\nThis project challenges that perception by presenting philosophy as **lively, conversational, and relevant**, encouraging reflection and intellectual curiosity through an engaging AI-based device.\\r\\n\\r\\n\\r\\n## Challenges\\r\\n\\r\\n- Flashing, configuring, and assembling the XiaoZhi AI hardware\\r\\n- Coordinating stable interaction between the two agents\\r\\n\\r\\n\\r\\n## Unique Characteristics\\r\\n\\r\\n- The choice of **Schopenhauer and Hegel** is intentional: their philosophical disagreements create natural tension and contrasting worldviews.\\r\\n- The physical shell is designed as a trendy **\u201cElegant Gentleman\u201d penguin**, serving as a visual hook and lowering the entry barrier to philosophical engagement.\\r\\n\\r\\n\\r\\n## Next Steps\\r\\n\\r\\nFuture development will explore additional applications of twin-agent systems.  \\r\\nOne example is a **vocabulary-learning mode** featuring two Minion-style agents:\\r\\n- One acts as the quiz master\\r\\n- The other provides encouragement, hints, and emotional support\\r\\n\\r\\nThis makes learning more interactive, motivating, and emotionally engaging."}]}}')}}]);